<?php

declare(strict_types=1);

namespace Labyrinthe\Connect\Model;

/**
 * Result of a multi-recipient send: one Message per (deduplicated) recipient.
 *
 * @implements \IteratorAggregate<int, Message>
 */
final class MessageBatch implements \IteratorAggregate, \Countable
{
    /**
     * @param list<Message> $messages
     */
    public function __construct(
        public readonly array $messages,
        /** The Idempotency-Key used for this send (yours, or the one generated by the SDK). */
        public readonly string $idempotencyKey,
        /** True when the API replayed an earlier identical request (nothing was sent again). */
        public readonly bool $replayed,
    ) {
    }

    public function first(): ?Message
    {
        return $this->messages[0] ?? null;
    }

    public function count(): int
    {
        return \count($this->messages);
    }

    /**
     * @return \ArrayIterator<int, Message>
     */
    public function getIterator(): \ArrayIterator
    {
        return new \ArrayIterator($this->messages);
    }
}
